def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            if kwargs:
                raise NotImplementedError("TTLCache does not support kwargs")
            key = args
            if key in cache:
                value, expiration = cache[key]
                if timer() - expiration > ttl:
                    del cache[key]
                    value = func(*args)
                    cache[key] = (value, timer())
            else:
                value = func(*args)
                cache[key] = (value, timer())
            return value
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            if args in cache:
                cache.move_to_end(args)
                return cache[args]
            else:
                result = func(*args, **kwargs)
                if len(cache) >= maxsize:
                    cache.popitem(last=False)
                cache[args] = result
                return result
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = {}
        def wrapper(*args, **kwargs):
            if args in cache:
                cache[args].count += 1
                return cache[args].value
            result = func(*args, **kwargs)
            if len(cache) >= maxsize:
                cache.pop(min(cache, key=lambda x: cache[x].count))
            cache[args] = {"count": 1, "value": result}
            return result
        return wrapper
    return decorator

