def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        raise ValueError("Invalid application object: missing spec.manifest")

    default_observer_schema = {}

    for resource in app.spec.manifest:
        resource_type = resource.kind
        if resource_type not in default_observer_schema:
            default_observer_schema[resource_type] = {}

        for container in resource.spec.containers:
            container_name = container.name
            if container_name not in default_observer_schema[resource_type]:
                default_observer_schema[resource_type][container_name] = {
                    "type": "object",
                    "properties": {
                        "ready": {
                            "type": "boolean"
                        },
                        "restartCount": {
                            "type": "integer"
                        },
                        "state": {
                            "type": "object",
                            "properties": {
                                "running": {
                                    "type": "object"
                                },
                                "waiting": {
                                    "type": "object"
                                },
                                "terminated": {
                                    "type": "object"
                                }
                            }
                        }
                    }
                }

    return default_observer_schema

