def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if extract_spec_version:
        spec_version = inventory.get('type')
        if spec_version is not None:
            spec_version = spec_version.split('v')[-1]
            if not spec_version.isdecimal():
                raise ValueError("Invalid spec version in inventory")
            self.spec_version = int(spec_version)

    # validate other fields in the inventory
    if 'items' not in inventory:
        raise KeyError("Items field is missing")
    if not isinstance(inventory['items'], list):
        raise ValueError("Items field is not a list")

    for item in inventory['items']:
        for key, value in item.items():
            if key not in self.item_names:
                raise KeyError(f"{key} is not a valid item name")
            if not isinstance(value, list):
                raise ValueError(f"{key} is not a list")
            for element in value:
                if not isinstance(element, (int, float)):
                    raise ValueError(f"{element} is not a number")

    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Check if all digests in manifest files are present
    for manifest_file in manifest_files:
        if manifest_file not in digests_used:
            raise ValueError(f"Digest {manifest_file} is not present in manifest.")

    # Check if all digests used are present in manifest files
    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError(f"Digest {digest} is not present in manifest.")

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for item in inventory:
        if item.logical_path.startswith(version):
            logical_path = item.logical_path.split("/")[1]
            content_files = set()
            for content_file in item.content_files:
                content_files.add(content_file.file_id)
            logical_path_map[logical_path] = content_files
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity:
        raise ValueError("Fixity block is empty")

    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    for algorithm, values in fixity.items():
        if not isinstance(algorithm, str):
            raise ValueError("Fixity algorithm must be a string")

        if not is_valid_fixity_algorithm(algorithm):
            raise ValueError("Invalid fixity algorithm: %s" % algorithm)

        if not isinstance(values, list):
            raise ValueError("Fixity values must be a list")

        for value in values:
            if not isinstance(value, str):
                raise ValueError("Fixity values must be strings")

            try:
                validate_fixity_value(value, algorithm)
            except ValueError as e:
                raise ValueError("Invalid fixity value: %s" % value) from e

    for file in manifest_files:
        file_path = file["path"]
        if file_path not in fixity:
            raise ValueError("File %s is missing fixity information" % file_path)

        fixity_value = fixity[file_path]
        if not isinstance(fixity_value, list):
            raise ValueError("Fixity value for file %s must be a list" % file_path)

        for value in fixity_value:
            try:
                validate_fixity_value(value, algorithm)
            except ValueError as e:
                raise ValueError("Invalid fixity value for file %s: %s" % (file_path, value)) from e

def files_list(path):
    """
    Return the files in `path`
    """
    try:
        if os.path.isdir(path):
            return [os.path.join(path, file) for file in os.listdir(path)]
        elif os.path.isfile(path):
            return [path]
        else:
            raise ValueError("{} is not a valid path".format(path))
    except OSError as e:
        raise e

def _eval_file(prefix, file_path):
    file_name, file_extension = os.path.splitext(file_path)
    file_name = file_name.lower()
    if file_extension == ".asset":
        file_type = "asset"
    elif file_extension == ".rendition":
        file_type = "rendition"
    else:
        raise ValueError("Invalid file extension")
    file_addr = os.path.join(prefix, file_name)
    return {"type": file_type, "addr": file_addr}

