def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, Or):
            if any(isinstance(arg.args[0], Or) and isinstance(arg.args[1], Or) for arg in arg.args):
                new_args.extend(absorb(self, arg.args))
            else:
                new_args.append(arg)
        elif isinstance(arg, And):
            if any(isinstance(arg.args[0], And) and isinstance(arg.args[1], And) for arg in arg.args):
                new_args.extend(absorb(self, arg.args))
            else:
                new_args.append(arg)
        elif isinstance(arg, Not):
            if isinstance(arg.args[0], Or):
                new_args.append(And(arg.args[0].args[0], arg.args[1]))
            elif isinstance(arg.args[0], And):
                new_args.append(Or(arg.args[0].args[0], arg.args[1]))
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

def tzname_in_python2(myfunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return myfunc(*args, **kwargs)
        else:
            return myfunc(*args, **kwargs).encode()
    return inner_func

def get_versions(paths=None, default="unknown"):
    """Get version information or return default if unable to do so."""
    try:
        f, p, i = find_module("version", paths)
        if f:
            f.close()
        return default
    except ImportError:
        return None

    v = get_module_constant("version", "__version__", default, paths)

    if v is not None and v is not default and format is not None:
        return format(v)

    return v

def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if style not in ['semver', 'pep440']:
        raise ValueError("Invalid style: %s" % style)

    # Join the version pieces with the appropriate separator
    if style == 'semver':
        separator = '.'
    else:
        separator = ''

    return separator.join(pieces)

