def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not isinstance(bug_ids, list):
        raise TypeError("bug_ids must be a list")
    for bug_id in bug_ids:
        if bug_id not in self._bugs:
            raise ValueError(f"Bug with id {bug_id} does not exist in Bugzilla")
        bug = self._bugs[bug_id]
        for key, value in params.items():
            if key in bug.__dict__:
                setattr(bug, key, value)
            else:
                raise ValueError(f"{key} is not a valid attribute of the Bug class")
    return self._bugs

def deep_merge_nodes(nodes):
    merged_nodes = {}
    for node in nodes:
        if isinstance(node[1], MappingNode):
            for key, value in node[1].value:
                if key in merged_nodes:
                    if isinstance(merged_nodes[key], MappingNode):
                        merged_nodes[key].value = deep_merge_nodes([(key, value)])
                    else:
                        merged_nodes[key] = value
                else:
                    merged_nodes[key] = value
        else:
            merged_nodes[node[0]] = node[1]
    return [(key, value) for key, value in merged_nodes.items()]

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    flags = []
    for action in parser._actions:
        flags.extend(action.option_strings)
    return " ".join(flags)

