def deep_merge_nodes(nodes):
    merged_nodes = {}
    for node in nodes:
        key = node[0]
        value = node[1]
        if key in merged_nodes:
            if type(value) is not list:
                merged_nodes[key] = value
            else:
                for item in value:
                    if item not in merged_nodes[key]:
                        merged_nodes[key].append(item)
        else:
            merged_nodes[key] = value
    return list(merged_nodes.items())

