def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    count = 0
    current_token = ""
    for char in frequency:
        if char.isdigit():
            count = count * 10 + int(char)
        elif char.isalpha():
            current_token += char
        else:
            raise ValueError("Invalid frequency string")

    if current_token == "s":
        count = 1
        current_token = "second"
    elif current_token == "m":
        count = 1
        current_token = "minute"
    elif current_token == "h":
        count = 1
        current_token = "hour"
    elif current_token == "d":
        count = 1
        current_token = "day"
    elif current_token == "w":
        count = 1
        current_token = "week"
    elif current_token == "M":
        count = 1
        current_token = "month"
    elif current_token == "y":
        count = 1
        current_token = "year"
    else:
        raise ValueError("Invalid time unit in frequency string")

    return datetime.timedelta(**{current_token: count})

