def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    if other is not None:
        if isinstance(other, np.ndarray):
            self.scale = other
        elif isinstance(other, float):
            self.scale = other
        else:
            raise ValueError("Invalid scale value, must be a numeric or ndarray")
    else:
        if hasattr(self, "x"):
            x = self.x.sum()
            y = self.y.sum()
            return math.sqrt(x**2 + y**2)
        elif hasattr(self, "y"):
            y = self.y.sum()
            return math.sqrt(y**2)
        elif hasattr(self, "z"):
            z = self.z.sum()
            return math.sqrt(z**2)
        else:
            raise ValueError("Invalid graph dimensions, must have at least 1 coordinate")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check that the candidate is a class
    if not inspect.isclass(candidate):
        raise TypeError("Candidate must be a class")

    # Check that the candidate has all the necessary methods
    for method in iface.getMethods():
        if not hasattr(candidate, method.name):
            raise AttributeError("Candidate is missing method %s" % method.name)

    # Check that the candidate's methods have the correct signatures
    for method in iface.getMethods():
        candidate_method = getattr(candidate, method.name)
        if not inspect.signature(candidate_method) == inspect.signature(method):
            raise TypeError("Candidate's method %s has the wrong signature" % method.name)

    # If the interface is tentative, we're not ready to check the implementation yet
    if tentative:
        return

    # Check that the candidate's methods have the correct behavior
    for method in iface.getMethods():
        candidate_method = getattr(candidate, method.name)
        if not _methods_have_same_behavior(method, candidate_method):
            raise RuntimeError("Candidate's method %s does not have the same behavior as the interface" % method.name)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
