def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if not isinstance(node, ET.Element):
        raise TypeError("Expected an xml.etree.ElementTree.Element, got %s" % type(node))

    children = node.getchildren()
    if not children:
        return {}

    children_dict = {}
    for child in children:
        tag = child.tag
        if tag in children_dict:
            if not isinstance(children_dict[tag], list):
                children_dict[tag] = [children_dict[tag]]
            children_dict[tag].append(child)
        else:
            children_dict[tag] = child

    return children_dict

