def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        cert = x509.load_pem_x509_certificate(public_key, backend=default_backend())
        pub_key = cert.public_key()
        signature_algo = signature["SignatureMethod"]["Algorithm"]
        hash_algo = signature["CanonicalizationMethod"]["Algorithm"]
        signed_info = signature["SignedInfo"]
        if hash_algo == "http://www.w3.org/2001/10/xml-exc-c14n#":
            canonicalized_signed_info = etree.tostring(signed_info, method="c14n")
        elif hash_algo == "http://www.w3.org/2001/10/xml-exc-c14n#WithComments":
            canonicalized_signed_info = etree.tostring(signed_info, method="c14n", with_comments=True)
        else:
            raise SAMLError("Unsupported CanonicalizationMethod algorithm: %s" % hash_algo)
        if signature_algo == "http://www.w3.org/2000/09/xmldsig#rsa-sha1":
            digest_method = hashes.SHA1()
        elif signature_algo == "http://www.w3.org/2001/04/xmldsig-more#rsa-sha224":
            digest_method = hashes.SHA224()
        elif signature_algo == "http://www.w3.org/2001/04/xmldsig-more#rsa-sha256":
            digest_method = hashes.SHA256()
        elif signature_algo == "http://www.w3.org/2001/04/xmldsig-more#rsa-sha384":
            digest_method = hashes.SHA384()
        elif signature_algo == "http://www.w3.org/2001/04/xmldsig-more#rsa-sha512":
            digest_method = hashes.SHA512()
        else:
            raise SAMLError("Unsupported SignatureMethod algorithm: %s" % signature_algo)
        verifier = pub_key.verifier(canonicalized_signed_info, signature_algo, backend=default_backend())
        verifier.update(digest_method)
        verifier.verify()
        return True
    except (ValueError, InvalidSignature):
        return False
    except Exception as exc:
        raise SAMLError(exc)

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse the document as JSON
        return json.loads(document)
    except json.JSONDecodeError:
        pass

    # If parsing as JSON failed, try to parse it as XRD
    xrd = XRD(document)
    parsed_links = {}
    for link in xrd.links:
        parsed_links[link.rel] = link.href

    return parsed_links

