def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if not hasattr(self, 'opt_specs'):
        raise RuntimeError('Option specs not found')
    if not isinstance(self.opt_specs, dict):
        raise TypeError('Option specs must be a dictionary')
    if command_name not in self.opt_specs:
        raise KeyError('Option specs for command {} not found'.format(command_name))
    spec_list = self.opt_specs[command_name]
    if not isinstance(spec_list, list):
        raise TypeError('Option specs for command {} must be a list'.format(command_name))
    for spec in spec_list:
        if not isinstance(spec, dict):
            raise TypeError('Option specs for command {} must be a dictionary'.format(command_name))
