    silent_args = []
    for arg in args:
        if arg.startswith('-'):
            silent_args.append(arg)
    return silent_args

def _validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if arg in self.parsed_yaml:
            value = self.parsed_yaml[arg]
            length = self.parsed_yaml.get("len_{}".format(arg), None)
            if length is not None:
                if not isinstance(length, int):
                    raise ValueError("Length must be an integer (got {})".format(type(length).__name__))
                if length < 0:
                    raise ValueError("Length must be non-negative (got {})".format(length))
                if len(value) > length:
                    raise ValueError("Value of '{}' is too long ({} > {})".format(arg, len(value), length))

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if hasattr(self, arg_name) and arg_name in self._choices:
            choices = self._choices[arg_name]
            if arg_value not in choices:
                raise ValueError(f"Invalid choice `{arg_value}` for argument `{arg_name}`. Acceptable values are: {choices}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if len(args) < 2:
        raise ValueError("Must provide at least 2 arguments.")
    if len(args) > 2:
        raise ValueError("Cannot provide more than 2 arguments.")
    if not (isinstance(args[0], int) and isinstance(args[1], int)):
        raise ValueError("Arguments must be of type int.")
    if args[0] > args[1]:
        raise ValueError("Minimum value must be less than or equal to maximum value.")
    return args[0], args[1]

def merge_extra_vars(vars_dict, extra_vars=None):
    if not vars_dict:
        vars_dict = {}
    if extra_vars:
        for key, value in extra_vars.items():
            vars_dict[key] = value
    return vars_dict

def _convert_non_cli_args(self, parser_name: str, values_dict: dict) -> None:
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    args_parser = self.args_parsers[parser_name]
    for opt in args_parser.options:
        if opt.name in values_dict:
            values_dict[opt.name] = opt.convert(values_dict[opt.name])
        elif opt.default is not None:
            values_dict[opt.name] = opt.convert(opt.default)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.environ.get("CONFIG_PATH"):
        os.environ["CONFIG_PATH"] = self.config_path
        _log.debug("Injected config path: {}".format(self.config_path))

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with root")
    return path[len(root):]
